(7615078, 1232304, 3306, '<td valign="top">This composition catches my eye. The horizontal lines on the sleeves balance the vertical lines of the piano. I like it in black and white. Very good eye. My favorite of the challenge.</td>', 'This composition catches my eye. The horizontal lines on the sleeves balance the vertical lines of the piano. I like it in black and white. Very good eye. My favorite of the challenge.', '2019-02-23 06:44:36.000000', NULL, 1),
(7615079, 1232862, 3306, '<td valign="top">Of course! Well done. Top 3 in my book!</td>', 'Of course! Well done. Top 3 in my book!', '2019-02-23 06:45:30.000000', NULL, 1),
(7615081, 1232410, 3306, '<td valign="top">Nicely composed and I like the colors. It shows you put thought into this contribution. Well done.</td>', 'Nicely composed and I like the colors. It shows you put thought into this contribution. Well done.', '2019-02-23 06:47:09.000000', NULL, 1),
(7615082, 1232858, 3306, '<td valign="top">Soft and pleasing to the eye. Delicate and feminine.</td>', 'Soft and pleasing to the eye. Delicate and feminine.', '2019-02-23 06:48:34.000000', NULL, 1),
(7615083, 1232909, 3306, '<td valign="top">A little disturbing but very well done! Quite creative for this challenge. Sort of takes my breath away.</td>', 'A little disturbing but very well done! Quite creative for this challenge. Sort of takes my breath away.', '2019-02-23 06:50:38.000000', NULL, 1),
(7615084, 1232904, 3306, '<td valign="top">I like your use of light in this composition. The soft contrast is very pleasing to the eye. Very nice!</td>', 'I like your use of light in this composition. The soft contrast is very pleasing to the eye. Very nice!', '2019-02-23 06:52:24.000000', NULL, 1),
(7615110, 1232912, 179769, '<td valign="top">I love the "worn out" quality of this.</td>', 'I love the "worn out" quality of this.', '2019-02-23 12:43:20.000000', NULL, 1),
(7615111, 1232736, 179769, '<td valign="top">Selective coloring isn''t usually terribly popular here at DPC, but I think this is really effective.</td>', 'Selective coloring isn''t usually terribly popular here at DPC, but I think this is really effective.', '2019-02-23 12:45:08.000000', NULL, 1),
(7615112, 1232304, 179769, '<td valign="top">As a pianist, the hand position is bothersome :-) , but a cute idea.</td>', 'As a pianist, the hand position is bothersome :-) , but a cute idea.', '2019-02-23 12:48:22.000000', NULL, 1),
(7615313, 1232862, 35545, '<td valign="top">As a hand spinner and hand weaver, I can say that the wool in this picture has a ways to go before it becomes a textile.  Having said that, I love this picture, especially the expression on the face of the big sheep in the foreground.  Nice bokeh and and definition in the fleece on the sheep.  Good work.</td>', 'As a hand spinner and hand weaver, I can say that the wool in this picture has a ways to go before it becomes a textile.  Having said that, I love this picture, especially the expression on the face of the big sheep in the foreground.  Nice bokeh and and definition in the fleece on the sheep.  Good work.', '2019-02-24 13:04:36.000000', NULL, 1),
(7615360, 1232800, 114285, '<td valign="top">Great environmental portrait, this is my top pick.</td>', 'Great environmental portrait, this is my top pick.', '2019-02-24 21:31:13.000000', NULL, 1),
